export const mediaInspectionBefore = {
  // Deleted from the tree as unreachable (slice 0); frozen here because the old bank mounted them.
  "src/svelte/catalog/renderer/public-catalog-bank/CatalogNavigation.svelte": "<script lang=\"ts\">\n  import { Button } from \"@desert/svelte/vendor/components/ui/button/index.js\";\n  import { ResolvedNodes } from \"../../../../interaction/catalog.ts\";\n  import { catalogGroups, navigateCatalog, type CatalogEntry } from \"../../../infra/catalog-navigation.ts\";\n  let { entries }: { entries: readonly CatalogEntry[] } = $props();\n</script>\n\n<nav id=\"catalog-navigation\" tabindex=\"-1\" aria-label=\"Catalog navigation\" class=\"flex flex-col gap-3 scroll-mt-4\">\n  <div class=\"flex flex-wrap items-center gap-2\">\n    {#each catalogGroups as group (group.family)}\n      {@const count = entries.filter(entry => entry.inspection.group === group.id).length}\n      {#if count > 0}\n        <Button variant=\"secondary\" size=\"sm\" class=\"max-w-full whitespace-normal text-left\" href={`#${group.anchor}`} onclick={event => navigateCatalog(event, group.anchor)}>\n          <span class=\"type-caption\">{group.title} <span aria-hidden=\"true\">\u00b7 {count}</span></span>\n        </Button>\n      {/if}\n    {/each}\n  </div>\n  <p role=\"status\" aria-live=\"polite\" class=\"type-caption text-muted-foreground\">\n    {entries.length} of {ResolvedNodes.entries.length} components \u00b7 {entries.reduce((count, entry) => count + entry.inspection.fixtures.length, 0)} fixtures\n  </p>\n</nav>\n",
  "src/svelte/catalog/renderer/public-catalog-bank/CatalogGroupHeader.svelte": "<script lang=\"ts\">\n  import { catalogGroups, type CatalogFamily } from \"../../../infra/catalog-navigation.ts\";\n  let { family }: { family: CatalogFamily } = $props();\n  let group = $derived(catalogGroups.find(group => group.family === family)!);\n</script>\n\n<header class=\"flex min-w-0 flex-col gap-2 px-4\">\n  <div class=\"flex flex-wrap items-start justify-between gap-3 pt-2\">\n    <div class=\"flex min-w-0 flex-col gap-1\">\n      <h2 id={group.anchor} tabindex=\"-1\" class=\"type-section scroll-mt-4 break-words\">{group.title}</h2>\n    </div>\n  </div>\n  <p class=\"type-caption text-muted-foreground max-w-prose\">{group.description}</p>\n</header>\n",
  "src/svelte/catalog/renderer/public-catalog-bank/CatalogFoundations.svelte": "<script lang=\"ts\">\n  import { ResolvedNodes } from \"../../../../interaction/catalog.ts\";\n</script>\n\n<!-- Shared rules, not another semantic inventory or a set of fake specimens. -->\n<section aria-label=\"Shared renderer owners\" class=\"flex min-w-0 flex-col gap-4 px-4\">\n  <p class=\"type-caption text-muted-foreground\">Six shared owners. Components below reuse these rules; a fixture does not imply full qualification.</p>\n  <dl class=\"grid min-w-0 gap-4 sm:grid-cols-2\">\n    {#each ResolvedNodes.foundations as owner (owner.id)}\n      <div data-foundation={owner.id} class=\"flex min-w-0 flex-col gap-1\">\n        <dt class=\"type-section\">{owner.title}</dt>\n        <dd class=\"type-caption text-muted-foreground\">{owner.rule}</dd>\n        <dd class=\"type-caption break-all text-muted-foreground\">{#each owner.sources as source}<code class=\"block\">{source}</code>{/each}</dd>\n      </div>\n    {/each}\n  </dl>\n</section>\n",
  "src/svelte/catalog/renderer/media-content/MediaContent.svelte": "<script lang=\"ts\">\n  import { setContext } from \"svelte\";\n  import type { MediaLibrary } from \"../../../../views/media-library.ts\";\n  import CatalogHome from \"../../compositions/catalog-home/CatalogHome.svelte\";\n  import Viewer from \"../../compositions/viewer/Viewer.svelte\";\n  import { catalogPhotos, type Photo } from \"../../../infra/media-source.ts\";\n  import { mediaContent, mediaImages, mediaTarget, mediaAlbum } from \"../../../infra/media-data.ts\";\n  let { library, album, onalbum }: {\n    library: MediaLibrary; album: string | null; onalbum: (id: string) => void;\n  } = $props();\n  let owner: HTMLDivElement;\n  let open = $state(false), index = $state(0), title = $state(\"\");\n  let photos = $state.raw<readonly Photo[]>([]);\n  let opener: HTMLElement | null = null;\n  setContext(\"catalog-photo-intent\", (record: string) => {\n    const target = mediaTarget(library, record);\n    return target?.kind === \"image\" ? target.image.image.asset\n      : target ? library.images.find(image => image.id === target.album.cover)?.image.asset : undefined;\n  });\n  export function select(record: string) {\n    const target = mediaTarget(library, record);\n    if (!target) return false;\n    if (target.kind === \"album\") { onalbum(target.album.id); return true; }\n    const current = mediaImages(library, album);\n    // A result outside the current album opens the library queue, not a wrong index.\n    const inAlbum = current.some(image => image.id === target.image.id);\n    const queue = inAlbum ? current : library.images;\n    index = queue.findIndex(image => image.id === target.image.id);\n    photos = catalogPhotos(queue.map(image => image.image));\n    title = inAlbum ? mediaAlbum(library, album)?.title ?? \"Media\" : \"Media\";\n    opener = owner.querySelector<HTMLElement>(`[data-record=\"${CSS.escape(record)}\"] button`);\n    open = true;\n    return true;\n  }\n  function returnFocus() {\n    const target = opener?.isConnected && opener.checkVisibility() ? opener\n      : owner.closest<HTMLElement>(\"[data-catalog-scroll]\");\n    target?.focus({ preventScroll: true });\n  }\n</script>\n\n<div bind:this={owner} data-media-library={library.id} data-media-album={album ?? undefined}>\n  <CatalogHome node={mediaContent(library, album)} bodyOnly\n    onevent={event => { if (event.kind === \"catalog.open\") select(event.record); }} />\n  {#if open}<Viewer {photos} {title} bind:index bind:open onreturn={returnFocus} />{/if}\n</div>\n",
  "src/svelte/catalog/renderer/inspection-content/InspectionContent.svelte": "<script lang=\"ts\">\n  import { tick } from \"svelte\";\n  import type { NodeEvent } from \"../../../../interaction/node-events.ts\";\n  import type { ResolvedNodeId } from \"../../../../interaction/catalog.ts\";\n  import type { PublicBankInput } from \"../../../infra/PublicCatalogBank-model.ts\";\n  import PublicCatalogBank from \"../public-catalog-bank/PublicCatalogBank.svelte\";\n  import RetainedPlace from \"../../compositions/retained-place/RetainedPlace.svelte\";\n  import NodeRenderer from \"../node-renderer/NodeRenderer.svelte\";\n  import Toolbar from \"../../compositions/toolbar/Toolbar.svelte\";\n  import { inspectionCatalog } from \"../../compositions/inspection/inspection-fixture.ts\";\n\n  let { catalog = inspectionCatalog }: {\n    catalog?: PublicBankInput;\n  } = $props();\n  let bank: PublicCatalogBank | undefined = $state();\n  let selected = $state<string | null>(null);\n  let detail = $derived(catalog.details.find(item => item.record === selected));\n  let opener: HTMLElement | null = null;\n  async function back() {\n    selected = null;\n    await tick();\n    if (opener?.isConnected) opener.focus({ preventScroll: true });\n  }\n  function interact(event: NodeEvent) {\n    if (event.kind === \"catalog.open\") {\n      if (!catalog.details.some(item => item.record === event.record)) throw new Error(\"UNKNOWN_INSPECTION_RECORD\");\n      opener = document.activeElement instanceof HTMLElement ? document.activeElement : null;\n      selected = event.record;\n    } else if (event.kind === \"catalog.back\") void back();\n  }\n  export async function revealEntry(id: ResolvedNodeId): Promise<HTMLElement | null> {\n    selected = null;\n    await tick();\n    return bank?.revealEntry(id) ?? null;\n  }\n</script>\n\n<RetainedPlace active={!detail}>\n  <PublicCatalogBank bind:this={bank} surface={catalog} oncatalog={interact} bodyOnly />\n</RetainedPlace>\n{#if detail}\n  <Toolbar toolbar={{ edge: \"top\", title: detail.title, subtitle: \"Local renderer example\", leading: {\n    intent: { kind: \"back\" }, icon: \"back\", label: \"Back to visual catalog\", state: \"ready\",\n  } }} invoke={() => void back()} />\n  <NodeRenderer node={detail} onevent={interact} />\n{/if}\n",
  "src/svelte/catalog/renderer/public-catalog-bank/PublicCatalogBank.svelte": "<script lang=\"ts\">\n  import { tick } from \"svelte\";\n  import type { NodeEvent } from \"../../../../interaction/node-events.ts\";\n  import type { ResolvedNodeId } from \"../../../../interaction/catalog.ts\";\n  import { catalogGroups } from \"../../../infra/catalog-navigation.ts\";\n  import { ResolvedNodes } from \"../../../../interaction/catalog.ts\";\n  import CatalogNavigation from \"./CatalogNavigation.svelte\";\n  import CatalogGroupHeader from \"./CatalogGroupHeader.svelte\";\n  import CatalogFoundations from \"./CatalogFoundations.svelte\";\n  import ControlBench from \"../../compositions/control-bench/ControlBench.svelte\";\n  import SpecimenGroup from \"../../compositions/specimen-group/SpecimenGroup.svelte\";\n  import SpecimenRow from \"../../compositions/specimen-row/SpecimenRow.svelte\";\n  import SpecimenUnavailable from \"../../compositions/specimen-unavailable/SpecimenUnavailable.svelte\";\n  import PublicCatalogBankSpecimen from \"../public-catalog-bank-specimen/PublicCatalogBankSpecimen.svelte\";\n  import { publicCatalogBankInventory, type PublicBankInput } from \"../../../infra/PublicCatalogBank-model.ts\";\n  import PlaceHeader from \"../../compositions/place-header/PlaceHeader.svelte\";\n  let { surface, oncatalog, bodyOnly = false }: {\n    surface: PublicBankInput; oncatalog: (event: NodeEvent) => void; bodyOnly?: boolean;\n  } = $props();\n  let inventory = $derived(publicCatalogBankInventory(surface));\n  const entries = ResolvedNodes.entries;\n  export async function revealEntry(id: ResolvedNodeId): Promise<HTMLElement | null> {\n    await tick();\n    return document.querySelector<HTMLElement>(`[data-public-catalog-bank] [data-catalog-entry=\"${id}\"]`);\n  }\n</script>\n\n<section data-public-catalog-bank class=\"flex w-full min-w-0 max-w-[52rem] flex-col gap-8\" aria-label=\"Component bank\">\n  {#if !bodyOnly}\n  <PlaceHeader title=\"Component bank\" subtitle=\"Interactive examples. Changes stay here; no product commands are executed.\" />\n  {/if}\n  <CatalogNavigation {entries} />\n  {#each catalogGroups as group (group.id)}\n    <section class=\"flex min-w-0 flex-col gap-8\" aria-label={group.title}>\n    <CatalogGroupHeader family={group.family} />\n    {#if group.id === \"foundations\"}<CatalogFoundations />{/if}\n    {#each group.entries.filter(entry => entry.family !== \"control\") as entry (entry.id)}\n    <SpecimenGroup id={entry.id}>\n      {#each inventory.filter(item => item.id === entry.id) as specimen (specimen.state)}\n        <SpecimenRow id={entry.id} state={specimen.state} coverage={specimen.gap ? \"gap\" : \"rendered\"}>\n          {#if specimen.node}<PublicCatalogBankSpecimen initial={specimen.node} {oncatalog} />\n          {:else if specimen.gap}<SpecimenUnavailable reason={specimen.gap} />{/if}\n        </SpecimenRow>\n      {/each}\n    </SpecimenGroup>\n    {/each}\n    <ControlBench entryIds={group.entries.filter(entry => entry.family === \"control\").map(entry => entry.id)} />\n    </section>\n  {/each}\n</section>\n"
} as const;
